def predict_global_distance(a,wall,metric='manhattan'):
 h,w=len(a),len(a[0]);mode=Counter(x for row in a for x in row).most_common(1)[0][0]
 # components of nonwall with majority label; active if label != mode
 seen=set();cc={};co=[]
 for r in range(h):
  for c in range(w):
   if a[r][c]!=wall and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));z=[]
    for x,y in q:
     z.append((x,y))
     for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
      p=x+dx,y+dy
      if 0<=p[0]<h and 0<=p[1]<w and a[p[0]][p[1]]!=wall and p not in seen:seen.add(p);q.append(p)
    ix=len(co);co.append(z)
    for p in z:cc[p]=ix
 labs={i:Counter(a[x][y] for x,y in z).most_common(1)[0][0] for i,z in enumerate(co)}
 colors=sorted(set(labs.values())-{mode,wall})
 cells={v:[p for i,z in enumerate(co) if labs[i]==v for p in z] for v in colors}
 out=[row[:] for row in a]
 for r in range(h):
  for c in range(w):
   if a[r][c]==wall:
    ds={}
    for v,ps in cells.items():
     if metric=='manhattan':d=min(abs(r-x)+abs(c-y) for x,y in ps)
     elif metric=='cheb':d=min(max(abs(r-x),abs(c-y)) for x,y in ps)
     elif metric=='euclid':d=min((r-x)**2+(c-y)**2 for x,y in ps)
     ds[v]=d
    md=min(ds.values());win=[v for v,d in ds.items() if d==md]
    if len(win)==1:out[r][c]=win[0]
 return out
